package checkpoint

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/stretchr/testify/require"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/storage/memory"
)

// lazyFetchRepo is a repo configured with a promisor remote whose transport is
// a fake recording helper: any git-internal lazy fetch invokes the helper and
// leaves a line in helperLog. Presence probes must never trip it (INC-78: one
// upload-pack request per missing blob per promisor remote).
type lazyFetchRepo struct {
	dir       string
	helperLog string
}

func (r lazyFetchRepo) lazyFetchAttempts(t *testing.T) int {
	t.Helper()
	data, err := os.ReadFile(r.helperLog)
	if os.IsNotExist(err) {
		return 0
	}
	require.NoError(t, err)
	return strings.Count(string(data), "\n")
}

// setupLazyFetchRepo initializes a repo with a promisor remote backed by a
// recording helper, chdirs into it (the FetchingTree git probes run in CWD),
// and returns it. Not parallel-safe: mutates CWD and PATH.
func setupLazyFetchRepo(t *testing.T) lazyFetchRepo {
	t.Helper()

	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "seed.txt", "seed")
	testutil.GitAdd(t, dir, "seed.txt")
	testutil.GitCommit(t, dir, "seed")

	helperDir := t.TempDir()
	helperLog := filepath.Join(helperDir, "invocations.log")
	script := fmt.Sprintf("#!/bin/sh\necho invoked >> %q\nexit 1\n", helperLog)
	require.NoError(t, os.WriteFile(filepath.Join(helperDir, "git-remote-testrec"), []byte(script), 0o755))
	t.Setenv("PATH", helperDir+string(os.PathListSeparator)+os.Getenv("PATH"))

	gitConfig(t, dir, "remote.lazy.url", "testrec::lazy")
	gitConfig(t, dir, "remote.lazy.fetch", "+refs/heads/*:refs/remotes/lazy/*")
	gitConfig(t, dir, "remote.lazy.promisor", "true")

	t.Chdir(dir)
	return lazyFetchRepo{dir: dir, helperLog: helperLog}
}

func gitConfig(t *testing.T, dir, key, value string) {
	t.Helper()
	cmd := exec.Command("git", "config", key, value)
	cmd.Dir = dir
	require.NoError(t, cmd.Run())
}

// absentBlobHash returns the hash of content that was never written to the
// object store.
func absentBlobHash(t *testing.T, dir string) plumbing.Hash {
	t.Helper()
	cmd := exec.Command("git", "hash-object", "--stdin")
	cmd.Dir = dir
	cmd.Stdin = strings.NewReader("never written to the object store\n")
	out, err := cmd.Output()
	require.NoError(t, err)
	return plumbing.NewHash(strings.TrimSpace(string(out)))
}

// mktree writes a tree with a single blob entry (which may be absent from the
// object store) and returns the parsed tree.
func mktree(t *testing.T, dir, name string, blob plumbing.Hash) *object.Tree {
	t.Helper()
	cmd := exec.Command("git", "mktree", "--missing")
	cmd.Dir = dir
	cmd.Stdin = strings.NewReader(fmt.Sprintf("100644 blob %s\t%s\n", blob, name))
	out, err := cmd.Output()
	require.NoError(t, err)

	repo, err := gitrepo.OpenPath(dir)
	require.NoError(t, err)
	tree, err := object.GetTree(repo.Storer, plumbing.NewHash(strings.TrimSpace(string(out))))
	require.NoError(t, err)
	return tree
}

func TestFetchingTree_CollectMissingBlobs_DoesNotLazyFetch(t *testing.T) {
	repo := setupLazyFetchRepo(t)
	missingHash := absentBlobHash(t, repo.dir)
	tree := mktree(t, repo.dir, "missing.txt", missingHash)

	gitRepo, err := gitrepo.OpenPath(repo.dir)
	require.NoError(t, err)
	ft := NewFetchingTree(context.Background(), tree, gitRepo.Storer, nil)

	missing := ft.CollectMissingBlobs()

	require.Equal(t, []plumbing.Hash{missingHash}, missing)
	require.Zero(t, repo.lazyFetchAttempts(t),
		"presence probe triggered git lazy fetch against the promisor remote")
}

func TestFetchingTree_File_MissingBlobWithoutFetcher_DoesNotLazyFetch(t *testing.T) {
	repo := setupLazyFetchRepo(t)
	missingHash := absentBlobHash(t, repo.dir)
	tree := mktree(t, repo.dir, "missing.txt", missingHash)

	gitRepo, err := gitrepo.OpenPath(repo.dir)
	require.NoError(t, err)
	ft := NewFetchingTree(context.Background(), tree, gitRepo.Storer, nil)

	_, err = ft.File("missing.txt")

	require.Error(t, err)
	require.Zero(t, repo.lazyFetchAttempts(t),
		"File fallback triggered git lazy fetch against the promisor remote")
}

func TestFetchingTree_CollectMissingBlobs_SeesOnDiskBlobInvisibleToStorer(t *testing.T) {
	repo := setupLazyFetchRepo(t)

	cmd := exec.Command("git", "hash-object", "-w", "--stdin")
	cmd.Dir = repo.dir
	cmd.Stdin = strings.NewReader("on disk but not in the storer\n")
	out, err := cmd.Output()
	require.NoError(t, err)
	onDiskHash := plumbing.NewHash(strings.TrimSpace(string(out)))
	tree := mktree(t, repo.dir, "ondisk.txt", onDiskHash)

	// An empty storer stands in for go-git's stale packfile-index view: the
	// blob is on disk but invisible to the storer, so only the git probe can
	// prove it local.
	ft := NewFetchingTree(context.Background(), tree, memory.NewStorage(), nil)

	require.Empty(t, ft.CollectMissingBlobs())
	require.Zero(t, repo.lazyFetchAttempts(t))
}

