// collectMissingBlobs recursively walks a tree and returns hashes of blob
// entries that are not present in the local object store. Entries missing
// from go-git's storer get a second opinion from a single batched git probe:
// in partial-clone repos a blob can be on disk but invisible to the storer
// (filtered out, or in a packfile not in the cached index).
func (t *FetchingTree) collectMissingBlobs(tree *object.Tree) []plumbing.Hash {
	candidates := t.storerMissingBlobs(tree)
	if len(candidates) == 0 {
		return nil
	}
	return t.blobsNotOnDisk(candidates)
}

// storerMissingBlobs recursively walks a tree and returns hashes of blob
// entries that go-git's storer cannot see.
func (t *FetchingTree) storerMissingBlobs(tree *object.Tree) []plumbing.Hash {
	var missing []plumbing.Hash
	for _, entry := range tree.Entries {
		if entry.Mode.IsFile() {
			if t.storer.HasEncodedObject(entry.Hash) != nil {
				missing = append(missing, entry.Hash)
			}
		} else {
			// Recurse into subtrees (tree objects are local after treeless fetch).
			subtree, err := tree.Tree(entry.Name)
			if err == nil {
				missing = append(missing, t.storerMissingBlobs(subtree)...)
			}
		}
	}
	return missing
}

// blobsNotOnDisk filters candidates to the hashes absent from the local
// object store, using one `git cat-file --batch-check` process for all of
// them. GIT_NO_LAZY_FETCH keeps the probe local-only: without it, git
// answers an absent object in a partial clone by lazy-fetching it from every
// promisor remote first — one upload-pack request per missing blob per
// remote, which is how a single `entire explain` produced ~1,800 requests
// and a git-protocol SLO P1 (INC-78). Fails open: if the probe itself fails,
// every candidate stays missing and the batched fetcher handles them.
func (t *FetchingTree) blobsNotOnDisk(candidates []plumbing.Hash) []plumbing.Hash {
	var input strings.Builder
	for _, h := range candidates {
		input.WriteString(h.String())
		input.WriteByte('\n')
	}

	cmd := exec.CommandContext(t.ctx, "git", "cat-file", "--batch-check")
	cmd.Env = append(cmd.Environ(), "GIT_NO_LAZY_FETCH=1")
	cmd.Stdin = strings.NewReader(input.String())
	out, err := cmd.Output()
	if err != nil {
		logging.Warn(t.ctx, "FetchingTree.blobsNotOnDisk: batch-check failed, treating all candidates as missing",
			slog.Int("count", len(candidates)),
			slog.String("error", err.Error()),
		)
		return candidates
	}

	// Present objects report "<oid> <type> <size>"; absent ones "<oid> missing".
	onDisk := make(map[plumbing.Hash]struct{})
	for line := range strings.Lines(string(out)) {
		fields := strings.Fields(line)
		if len(fields) >= 2 && fields[1] != "missing" {
			onDisk[plumbing.NewHash(fields[0])] = struct{}{}
		}
	}

	var missing []plumbing.Hash
	for _, h := range candidates {
		if _, ok := onDisk[h]; !ok {
			missing = append(missing, h)
		}
	}
	return missing
}

