package cli

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"os/exec"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/interactive"

	"github.com/spf13/cobra"
)

// partialCloneProbeBudget bounds the missing-object walk: rev-list is not
// context-cancellable from the inside, and doctor runs with a user waiting.
// On breach the result is inconclusive and the check degrades to warn-only.
const partialCloneProbeBudget = 10 * time.Second

// partialCloneRemote is a named remote carrying partial-clone config in the
// repo's local git config.
type partialCloneRemote struct {
	name        string
	promisor    bool
	cloneFilter bool
}

func (r partialCloneRemote) configKeys() []string {
	var keys []string
	if r.promisor {
		keys = append(keys, "remote."+r.name+".promisor")
	}
	if r.cloneFilter {
		keys = append(keys, "remote."+r.name+".partialclonefilter")
	}
	return keys
}

// checkPartialCloneConfig detects promisor/partialclonefilter config on named
// remotes and repairs it when it is provably a leftover.
//
// A filtered fetch against a remote *name* makes git persist
// remote.<name>.promisor and remote.<name>.partialclonefilter — config that is
// byte-identical to a genuine `git clone --filter` partial clone. Old Entire
// releases leaked it (#712); current ones fetch by URL to avoid it, but never
// repaired existing leaks. The leak is not inert: every git command that meets
// a missing object lazy-fetches it from the promisor remote (one upload-pack
// request per object per remote — the INC-78 amplification), and `git gc` may
// drop local objects it believes the promisor still holds.
//
// The config alone cannot distinguish leak from intent, so the local object
// store is the tiebreaker: a repo with no missing objects gets nothing from
// promisor config and the removal is safe (offered via prompt or --force),
// while a repo with missing objects — or an inconclusive probe — is treated as
// a possibly-genuine partial clone and only gets copy-paste repair steps,
// never an automatic fix. URL-keyed sections are skipped: Entire's own
// filtered fetches create those on purpose (see stampNewlyCreatedRemote).
func checkPartialCloneConfig(cmd *cobra.Command, force bool) error {
	ctx := cmd.Context()
	w := cmd.OutOrStdout()

	remotes, err := promisorConfiguredRemotes(ctx)
	if err != nil || len(remotes) == 0 {
		// Unreadable config means no repo here; sibling checks report that.
		return nil //nolint:nilerr // absence of a readable repo is a clean skip
	}

	missing, probeErr := repoHasMissingObjects(ctx)
	if probeErr != nil || missing {
		fmt.Fprintln(w, "Partial-clone config: FOUND")
		for _, r := range remotes {
			fmt.Fprintf(w, "  Remote %q is configured as a promisor remote and this repo is missing\n", r.name)
			fmt.Fprintln(w, "  objects locally, so it looks like a real partial clone. If that is")
			fmt.Fprintln(w, "  intentional, ignore this. If not (e.g. config leaked by an old Entire")
			fmt.Fprintln(w, "  filtered fetch, then hollowed out by `git gc`), repair with:")
			fmt.Fprintf(w, "    git fetch --refetch --no-filter %s\n", r.name)
			for _, key := range r.configKeys() {
				fmt.Fprintf(w, "    git config --unset %s\n", key)
			}
		}
		return nil
	}

	for _, r := range remotes {
		fmt.Fprintln(w, "Partial-clone config: LEAKED")
		fmt.Fprintf(w, "  Remote %q is configured as a promisor remote (%s),\n", r.name, strings.Join(r.configKeys(), ", "))
		fmt.Fprintln(w, "  but this repo has no missing objects — the config is a leftover, most")
		fmt.Fprintln(w, "  likely from an old Entire filtered fetch. It makes ordinary git commands")
		fmt.Fprintln(w, "  lazy-fetch missing objects one at a time from a remote that cannot serve")
		fmt.Fprintln(w, "  them, and lets `git gc` drop local objects.")
		fmt.Fprintf(w, "  Fix: remove the partial-clone config from remote %q.\n", r.name)

		if !force {
			if !interactive.CanPromptInteractively() {
