// promisorConfiguredRemotes returns the named remotes whose local config
// carries promisor or partialclonefilter keys. URL-keyed sections (which
// contain ":" — forbidden in remote names) are Entire's own adhoc filtered
// fetch remotes and are skipped.
func promisorConfiguredRemotes(ctx context.Context) ([]partialCloneRemote, error) {
	cmd := exec.CommandContext(ctx, "git", "config", "--local", "--get-regexp", `^remote\..*\.(promisor|partialclonefilter)$`)
	out, err := cmd.Output()
	if err != nil {
		// Exit 1 means no matching keys; anything else means no readable repo.
		var exitErr *exec.ExitError
		if errAs(err, &exitErr) && exitErr.ExitCode() == 1 {
			return nil, nil
		}
		return nil, fmt.Errorf("read git config: %w", err)
	}

	byName := make(map[string]*partialCloneRemote)
	var order []string
	for line := range strings.Lines(string(out)) {
		key, _, _ := strings.Cut(strings.TrimSpace(line), " ")
		name, isPromisor := strings.CutSuffix(strings.TrimPrefix(key, "remote."), ".promisor")
		if !isPromisor {
			name = strings.TrimSuffix(name, ".partialclonefilter")
		}
		if name == "" || strings.Contains(name, ":") {
			continue
		}
		r, ok := byName[name]
		if !ok {
			r = &partialCloneRemote{name: name}
			byName[name] = r
			order = append(order, name)
		}
		if isPromisor {
			r.promisor = true
		} else {
			r.cloneFilter = true
		}
	}

	remotes := make([]partialCloneRemote, 0, len(order))
	for _, name := range order {
		remotes = append(remotes, *byName[name])
	}
	return remotes, nil
}

// repoHasMissingObjects reports whether any object reachable from a ref is
// absent from the local object store. GIT_NO_LAZY_FETCH keeps the walk
// local-only; an inconclusive walk (budget breach, huge line, git error)
// returns an error and the caller must fail safe.
func repoHasMissingObjects(ctx context.Context) (bool, error) {
	ctx, cancel := context.WithTimeout(ctx, partialCloneProbeBudget)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "rev-list", "--objects", "--missing=print", "--all")
	cmd.Env = append(cmd.Environ(), "GIT_NO_LAZY_FETCH=1")
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return false, fmt.Errorf("rev-list stdout: %w", err)
	}
	if err := cmd.Start(); err != nil {
		return false, fmt.Errorf("rev-list start: %w", err)
	}

	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for scanner.Scan() {
		if strings.HasPrefix(scanner.Text(), "?") {
			// First missing object settles it; stop the walk early.
			_ = cmd.Process.Kill()
			_, _ = io.Copy(io.Discard, stdout)
			_ = cmd.Wait()
			return true, nil
		}
	}
	if scanErr := scanner.Err(); scanErr != nil {
		_ = cmd.Process.Kill()
		_ = cmd.Wait()
		return false, fmt.Errorf("rev-list read: %w", scanErr)
	}
	if err := cmd.Wait(); err != nil {
		return false, fmt.Errorf("rev-list: %w", err)
	}
	return false, nil
}

func removePartialCloneConfig(ctx context.Context, r partialCloneRemote) error {
	for _, key := range r.configKeys() {
		cmd := exec.CommandContext(ctx, "git", "config", "--unset", key)
		if out, err := cmd.CombinedOutput(); err != nil {
			return fmt.Errorf("git config --unset %s: %w (%s)", key, err, strings.TrimSpace(string(out)))
		}
	}
	return nil
}

