// abandonWalk kills a mid-stream rev-list and reaps it. Best-effort: the
// answer is already known, so teardown failures change nothing.
func abandonWalk(cmd *exec.Cmd, stdout io.Reader) {
	cmd.Process.Kill()             //nolint:errcheck,gosec // best-effort teardown
	io.Copy(io.Discard, stdout)    //nolint:errcheck,gosec // drain so Wait can't block on the pipe
	cmd.Wait()                     //nolint:errcheck,gosec // reap; exit status is irrelevant after Kill
}

